import { logger } from "../lib/logger";

const router: IRouter = Router();

interface ProofStep {
  id: string;
  type: "definition" | "axiom" | "lemma" | "theorem" | "proof" | "corollary" | "conclusion";
  title: string;
  claim: string;
  reasoning: string;
  notation: string;
  confidence: number;
}

interface Proof {
  id: string;
  title: string;
  abstract: string;
  category: string;
  author: string;
